mapper.select:
SELECT ar.*, r.name as resource_name, r.status as resource_status FROM appointment_resources ar LEFT JOIN resource r ON ar.resource_id = r.id WHERE ar.appointment_id IN
#{id}
ORDER BY ar.appointment_id, ar.resource_type, ar.resource_id

SELECT ar.*, a.appointment_date, a.appointment_time, a.status as appointment_status
FROM appointment_resources ar
LEFT JOIN appointments a ON ar.appointment_id = a.id
WHERE ar.resource_id = #{resourceId}
AND a.appointment_date = #{date}
AND a.status IN ('CONFIRMED', 'IN_PROGRESS')

mapper.update:
UPDATE appointment_resources 
SET is_primary = #{isPrimary}
WHERE appointment_id = #{appointmentId} AND resource_id = #{resourceId}

mapper.select:
SELECT COUNT(*) > 0 
FROM appointment_resources ar
JOIN appointments a ON ar.appointment_id = a.id
WHERE ar.resource_id = #{resourceId}
AND a.appointment_date = #{date}
AND a.appointment_time = #{time}
AND a.status IN ('CONFIRMED', 'IN_PROGRESS')

    AND a.id != #{excludeAppointmentId}
